import type { ApiErrorBody, CellChange, SelectionRect, WorkbookSnapshot, WorkbookSummary, WorksheetSnapshot } from '../../../shared/types';

/** Error carrying the HTTP status and the server-supplied `{error:{code,message}}`. */
export class ApiClientError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.name = 'ApiClientError';
    this.status = status;
    this.code = code;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(path, {
      headers: { 'Content-Type': 'application/json' },
      ...init,
    });
  } catch {
    throw new ApiClientError(0, 'NETWORK_ERROR', 'Could not reach the server. Please retry.');
  }

  const text = await response.text();
  let body: unknown = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = null;
    }
  }

  if (!response.ok) {
    const parsed = body as ApiErrorBody | null;
    throw new ApiClientError(
      response.status,
      parsed?.error?.code ?? 'ERROR',
      parsed?.error?.message ?? `Request failed with status ${response.status}`,
    );
  }
  return body as T;
}

export interface CellWriteResponse {
  updatedAt: string;
  changes: CellChange[];
  removed: { row: number; col: number }[];
}

export interface WorksheetPatchResponse {
  updatedAt: string;
  worksheet: WorksheetSnapshot;
}

function worksheetPath(workbookId: string, worksheetId: string): string {
  return `/api/workbooks/${encodeURIComponent(workbookId)}/worksheets/${encodeURIComponent(worksheetId)}`;
}

/** Same-origin `/api` client; the production build is served by the backend on the same PORT. */
export const api = {
  listWorkbooks(): Promise<WorkbookSummary[]> {
    return request<WorkbookSummary[]>('/api/workbooks');
  },
  getWorkbook(workbookId: string): Promise<WorkbookSnapshot> {
    return request<WorkbookSnapshot>(`/api/workbooks/${encodeURIComponent(workbookId)}`);
  },
  putCells(workbookId: string, worksheetId: string, changes: CellChange[]): Promise<CellWriteResponse> {
    return request<CellWriteResponse>(`${worksheetPath(workbookId, worksheetId)}/cells`, {
      method: 'PUT',
      body: JSON.stringify({ changes }),
    });
  },
  putSelection(
    workbookId: string,
    worksheetId: string,
    selection: SelectionRect,
  ): Promise<{ ok: true; selection: SelectionRect }> {
    return request<{ ok: true; selection: SelectionRect }>(
      `${worksheetPath(workbookId, worksheetId)}/selection`,
      { method: 'PUT', body: JSON.stringify(selection) },
    );
  },
  patchWorksheet(
    workbookId: string,
    worksheetId: string,
    patch: { name?: string; isActive?: boolean },
  ): Promise<WorksheetPatchResponse> {
    return request<WorksheetPatchResponse>(worksheetPath(workbookId, worksheetId), {
      method: 'PATCH',
      body: JSON.stringify(patch),
    });
  },
};

