import { describe, expect, it } from 'vitest';
import request from 'supertest';
import { migrate, openDatabase } from './db.js';
import {
  SEED_SHEET1_ID,
  SEED_SHEET2_ID,
  SEED_WORKBOOK_ID,
  SEED_WORKBOOK_NAME,
  seedDatabase,
} from './seed.js';
import { createApp } from './app.js';

function freshDb() {
  const db = openDatabase(':memory:');
  seedDatabase(db);
  return db;
}

/** @param {import('./db.js').Db} db */
function appFor(db) {
  return createApp(db, { frontendDist: null });
}

/**
 * @param {import('./db.js').Db} db
 * @param {string} table
 */
function countRows(db, table) {
  return /** @type {{ n: number }} */ (db.prepare(`SELECT COUNT(*) AS n FROM ${table}`).get()).n;
}

describe('migrations', () => {
  it('are repeatable and create the contract tables', () => {
    const db = openDatabase(':memory:');
    migrate(db);
    migrate(db);
    const tables = /** @type {{ name: string }[]} */ (
      db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all()
    ).map((r) => r.name);
    for (const table of [
      'workbooks',
      'worksheets',
      'cells',
      'validation_rules',
      'filters',
      'pivots',
      'schema_migrations',
    ]) {
      expect(tables).toContain(table);
    }
    expect(countRows(db, 'schema_migrations')).toBe(1);
  });
});

describe('seed', () => {
  it('is idempotent across restarts', () => {
    const db = freshDb();
    seedDatabase(db);
    seedDatabase(db);
    expect(countRows(db, 'workbooks')).toBe(1);
    expect(countRows(db, 'worksheets')).toBe(2);
    expect(countRows(db, 'cells')).toBe(12);
  });

  it('never overwrites existing user data', () => {
    const db = freshDb();
    db.prepare('UPDATE cells SET raw = ? WHERE worksheet_id = ? AND row = 1 AND col = 1').run(
      '999',
      SEED_SHEET1_ID,
    );
    seedDatabase(db);
    const value = /** @type {{ raw: string }} */ (
      db
        .prepare('SELECT raw FROM cells WHERE worksheet_id = ? AND row = 1 AND col = 1')
        .get(SEED_SHEET1_ID)
    );
    expect(value.raw).toBe('999');
  });

  it('creates the Q3 Sales workbook with the documented cells', () => {
    const db = freshDb();
    const rows = /** @type {{ row: number, col: number, raw: string }[]} */ (
      db
        .prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ? ORDER BY row, col')
        .all(SEED_SHEET1_ID)
    );
    expect(rows).toEqual([
      { row: 0, col: 0, raw: 'Region' },
      { row: 0, col: 1, raw: 'Sales' },
      { row: 0, col: 2, raw: 'Status' },
      { row: 1, col: 0, raw: 'East' },
      { row: 1, col: 1, raw: '1200' },
      { row: 1, col: 2, raw: 'Open' },
      { row: 2, col: 0, raw: 'North' },
      { row: 2, col: 1, raw: '800' },
      { row: 2, col: 2, raw: 'Closed' },
      { row: 3, col: 0, raw: 'South' },
      { row: 3, col: 1, raw: '700' },
      { row: 3, col: 2, raw: 'Open' },
    ]);
    const sheet2 = /** @type {{ n: number }} */ (
      db.prepare('SELECT COUNT(*) AS n FROM cells WHERE worksheet_id = ?').get(SEED_SHEET2_ID)
    );
    expect(sheet2.n).toBe(0);
  });
});

describe('GET /api/workbooks', () => {
  it('lists the seeded workbook with its last-updated value', async () => {
    const res = await request(appFor(freshDb())).get('/api/workbooks');
    expect(res.status).toBe(200);
    expect(res.body).toHaveLength(1);
    expect(res.body[0]).toMatchObject({ id: SEED_WORKBOOK_ID, name: SEED_WORKBOOK_NAME });
