import { describe, expect, it } from 'vitest';
import { CsvParseError, csvColumnCount, parseCsv, workbookNameFromFileName } from './csv.js';

/**
 * REQ-1-3-1 / Issue #3 decision D-A5: the parser accepts everything except the
 * one invalid class the requirement names (a field opening a quote that never
 * closes). These cases are the acceptance matrix for that rule.
 */
describe('parseCsv', () => {
  it('parses plain rows and columns in order', () => {
    expect(parseCsv('a,b,c\n1,2,3')).toEqual([
      ['a', 'b', 'c'],
      ['1', '2', '3'],
    ]);
  });

  it('preserves empty fields, including trailing ones', () => {
    expect(parseCsv('a,,c')).toEqual([['a', '', 'c']]);
    expect(parseCsv('a,b\nc,d,')).toEqual([
      ['a', 'b'],
      ['c', 'd', ''],
    ]);
    expect(parseCsv(',,')).toEqual([['', '', '']]);
  });

  it('handles commas inside double quotes', () => {
    expect(parseCsv('"a,b",c')).toEqual([['a,b', 'c']]);
  });

  it('collapses escaped quote pairs', () => {
    expect(parseCsv('"he said ""hi""",x')).toEqual([['he said "hi"', 'x']]);
    expect(parseCsv('""""')).toEqual([['"']]);
  });

  it('keeps line breaks inside quoted fields verbatim', () => {
    expect(parseCsv('"line1\nline2",b')).toEqual([['line1\nline2', 'b']]);
    expect(parseCsv('"line1\r\nline2",b')).toEqual([['line1\r\nline2', 'b']]);
  });

  it('accepts UTF-8 Chinese, English and numeric text', () => {
    expect(parseCsv('地区,销售额,状态\n华东,1200,完成')).toEqual([
      ['地区', '销售额', '状态'],
      ['华东', '1200', '完成'],
    ]);
  });

  it('treats LF, CRLF and lone CR as record separators', () => {
    const expected = [
      ['a', 'b'],
      ['c', 'd'],
    ];
    expect(parseCsv('a,b\nc,d')).toEqual(expected);
    expect(parseCsv('a,b\r\nc,d')).toEqual(expected);
    expect(parseCsv('a,b\rc,d')).toEqual(expected);
  });

  it('does not create a record for a trailing newline or trailing blank lines', () => {
    expect(parseCsv('a,b\n')).toEqual([['a', 'b']]);
    expect(parseCsv('a,b\r\n')).toEqual([['a', 'b']]);
    expect(parseCsv('a,b\n\n')).toEqual([['a', 'b']]);
    expect(parseCsv('\n')).toEqual([]);
    expect(parseCsv('\n\n')).toEqual([]);
  });

  it('returns no records for an empty file or a BOM-only file', () => {
    expect(parseCsv('')).toEqual([]);
    expect(parseCsv('\ufeff')).toEqual([]);
  });

  it('strips a leading BOM and keeps the first field intact', () => {
    expect(parseCsv('\ufeff地区,销售额')).toEqual([['地区', '销售额']]);
  });

  it('treats a bare quote inside an unquoted field as a literal character', () => {
    expect(parseCsv('ab"cd,e')).toEqual([['ab"cd', 'e']]);
    expect(parseCsv('a"b"c')).toEqual([['a"b"c']]);
  });

  it('accepts a quoted field with trailing text after the closing quote', () => {
    // Documented assumption A-5: only the requirement's invalid class is rejected.
    expect(parseCsv('"ab"cd,e')).toEqual([['abcd', 'e']]);
  });

  it('rejects a field that opens a quote and never closes it', () => {
    expect(() => parseCsv('a,"b')).toThrow(CsvParseError);
    expect(() => parseCsv('"')).toThrow(CsvParseError);
    expect(() => parseCsv('"unterminated\nnext,row')).toThrow(CsvParseError);
    expect(() => parseCsv('a,"b\n"c')).toThrow(CsvParseError);
    expect(() => parseCsv('a,b\n"x')).toThrow(/Invalid CSV file format/);
  });

  it('accepts a quoted field that is closed at the very end of the input', () => {
    expect(parseCsv('"a,b"')).toEqual([['a,b']]);
    expect(parseCsv('"a\nb"')).toEqual([['a\nb']]);
  });

  it('keeps blank lines in the middle as empty records', () => {
    expect(parseCsv('a\n\nb')).toEqual([['a'], [''], ['b']]);
  });
});

describe('csvColumnCount', () => {
  it('reports the widest record, or 0 for empty input', () => {
    expect(csvColumnCount([])).toBe(0);
    expect(csvColumnCount([['a'], ['a', 'b', 'c'], ['a', 'b']])).toBe(3);
  });
});

describe('workbookNameFromFileName', () => {
  it('drops a trailing .csv case-insensitively', () => {
    expect(workbookNameFromFileName('report.csv', 'Untitled spreadsheet')).toBe('report');
    expect(workbookNameFromFileName('Report.CSV', 'Untitled spreadsheet')).toBe('Report');
    expect(workbookNameFromFileName('  data.csv  ', 'Untitled spreadsheet')).toBe('data');
  });

  it('falls back when nothing usable remains', () => {
    expect(workbookNameFromFileName('.csv', 'Untitled spreadsheet')).toBe('Untitled spreadsheet');
    expect(workbookNameFromFileName('   ', 'Untitled spreadsheet')).toBe('Untitled spreadsheet');
  });

  it('keeps inner dots and only strips the final extension', () => {
    expect(workbookNameFromFileName('q3.sales.csv', 'Untitled spreadsheet')).toBe('q3.sales');
  });
});

