import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { api } from '../api/client';
import { DEFAULT_WORKBOOK_NAME, WORKBOOK_NAME_EMPTY_MESSAGE } from '../lib/copy';
import { messageOf } from '../lib/errors';

let uid = 0;

/**
 * `/new` — creation page for REQ-1-2-1 (Issue #3 decision D-A1).
 *
 * The name box is prefilled with the backend default (`Untitled spreadsheet`),
 * so "click Create immediately" and "clear and retype" cannot produce two
 * different names for the same intent. An empty (trimmed) name never reaches
 * the network: the exact requirement message is shown in place and the input is
 * preserved. Only a 201 response navigates to the editor, so a failed attempt
 * cannot leave a half-created record behind.
 */
export function NewWorkbookPage() {
  const navigate = useNavigate();
  const [name, setName] = useState(DEFAULT_WORKBOOK_NAME);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [inputId] = useState(() => `new-workbook-name-${(uid += 1)}`);

  const submit = async () => {
    const trimmed = name.trim();
    if (!trimmed) {
      setError(WORKBOOK_NAME_EMPTY_MESSAGE);
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      const created = await api.createWorkbook(trimmed);
      navigate(`/workbook/${encodeURIComponent(created.id)}`);
    } catch (caught) {
      // Keep the input and the page so the user can retry; the server created
      // nothing, so the home page list is unchanged.
      setError(messageOf(caught));
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-sheet-bg">
      <header className="flex h-14 items-center gap-3 border-b-1 border-sheet-border bg-white px-6">
        <Link to="/" className="text-sm text-sheet-accent hover:underline">
          ← Workbooks
        </Link>
      </header>

      <main className="mx-auto max-w-md px-6 py-10">
        <h1 className="mb-6 text-xl font-medium text-sheet-text">Create workbook</h1>
        <form
          onSubmit={(event) => {
            event.preventDefault();
            void submit();
          }}
          className="rounded-lg border-1 border-sheet-border bg-white p-6"
        >
          <label htmlFor={inputId} className="mb-1 block text-sm text-sheet-text">
            Workbook name
          </label>
          <input
            id={inputId}
            value={name}
            autoFocus
            onChange={(event) => {
              setName(event.target.value);
              setError(null);
            }}
            className="mb-4 w-full rounded border-1 border-sheet-border px-2 py-1.5 text-sm text-sheet-text outline-none"
          />
          {error ? (
            <p role="alert" className="mb-3 text-sm text-sheet-danger">
              {error}
            </p>
          ) : null}
          <div className="flex items-center gap-2">
            <button
              type="submit"
              disabled={submitting}
              className="rounded bg-sheet-accent px-4 py-1.5 text-sm text-white disabled:opacity-60"
            >
              Create
            </button>
            <Link to="/" className="sheet-button">
              Cancel
            </Link>
          </div>
        </form>
      </main>
    </div>
  );
}

