import { describe, expect, it } from 'vitest';
import type { CellEntry, WorksheetSnapshot } from '../../../shared/types';
import { csvFileName, escapeCsvField, worksheetToCsv } from './csvExport';

function sheet(cells: CellEntry[], rowCount = 6, colCount = 26): WorksheetSnapshot {
  return {
    id: 'ws-1',
    name: 'Sheet1',
    position: 0,
    isActive: true,
    rowCount,
    colCount,
    cells,
    lastSelection: null,
    validations: [],
    filters: [],
    pivots: [],
  };
}

describe('escapeCsvField', () => {
  it('leaves plain values untouched', () => {
    expect(escapeCsvField('Region')).toBe('Region');
    expect(escapeCsvField('1200')).toBe('1200');
    expect(escapeCsvField('')).toBe('');
    expect(escapeCsvField('华东')).toBe('华东');
  });

  it('quotes fields containing a comma, quote or line break', () => {
    expect(escapeCsvField('a,b')).toBe('"a,b"');
    expect(escapeCsvField('a"b')).toBe('"a""b"');
    expect(escapeCsvField('a\nb')).toBe('"a\nb"');
    expect(escapeCsvField('a\rb')).toBe('"a\rb"');
  });

  it('doubles every inner quote', () => {
    expect(escapeCsvField('"quoted"')).toBe('"""quoted"""');
  });
});

describe('worksheetToCsv', () => {
  it('serializes the seeded A1:C4 range as LF-terminated records', () => {
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'Region'],
        [0, 1, 'Sales'],
        [0, 2, 'Status'],
        [1, 0, 'East'],
        [1, 1, '1200'],
        [1, 2, 'Open'],
        [2, 0, 'North'],
        [2, 1, '800'],
        [2, 2, 'Closed'],
        [3, 0, 'South'],
        [3, 1, '700'],
        [3, 2, 'Open'],
      ]),
    );
    expect(csv).toBe(
      'Region,Sales,Status\nEast,1200,Open\nNorth,800,Closed\nSouth,700,Open\n',
    );
    expect(csv).not.toContain('\r');
    expect(csv.charCodeAt(0)).not.toBe(0xfeff);
  });

  it('trims trailing all-empty rows and columns but keeps gaps inside the used range', () => {
    // A1 and C3 are filled: the box is A1:C3, B2 stays an empty field.
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'a'],
        [2, 2, 'c'],
      ]),
    );
    expect(csv).toBe('a,,\n,,\n,,c\n');
  });

  it('exports an empty string for a worksheet with no content', () => {
    expect(worksheetToCsv(sheet([]))).toBe('');
    // Explicit empty cells (`raw === ''`) are not content.
    expect(worksheetToCsv(sheet([[0, 0, '']]))).toBe('');
  });

  it('escapes in place without changing row/column order', () => {
    const csv = worksheetToCsv(
      sheet([
        [0, 0, 'comma,value'],
        [0, 1, 'quote"value'],
        [0, 2, 'line\nbreak'],
        [1, 0, ''],
      ]),
    );
    expect(csv).toBe('"comma,value","quote""value","line\nbreak"\n,,,\n');
  });

  it('exports the value produced by the injected display seam', () => {
    // D-A8: the export never reads the raw text directly. Sub-issue C replaces
    // the seam with the formula engine, which is what makes a formula cell
    // export its calculated result instead of its expression.
    const worksheet = sheet([
      [0, 0, '=1+1'],
      [0, 1, 'plain'],
    ]);
    const csv = worksheetToCsv(worksheet, (row, col) => (row === 0 && col === 0 ? '2' : 'plain'));
    expect(csv).toBe('2,plain\n');
  });
});

describe('csvFileName', () => {
  it('suggests a name ending in .csv', () => {
    expect(csvFileName('Q3 Sales')).toBe('Q3 Sales.csv');
    expect(csvFileName('  预算  ')).toBe('预算.csv');
  });

  it('does not double an existing .csv extension', () => {
    expect(csvFileName('report.csv')).toBe('report.csv');
    expect(csvFileName('report.CSV')).toBe('report.CSV');
  });

  it('falls back to a usable base name', () => {
    expect(csvFileName('   ')).toBe('workbook.csv');
  });
});

