import { describe, expect, it } from 'vitest';
import type { WorksheetSnapshot } from '../../../shared/types';
import { worksheetDisplayValues } from './cellDisplay';

function sheet(cells: [number, number, string][]): WorksheetSnapshot {
  return {
    id: 'ws-1',
    name: 'Sheet1',
    position: 0,
    isActive: true,
    rowCount: 6,
    colCount: 26,
    cells,
    lastSelection: null,
    validations: [],
    filters: [],
    pivots: [],
  };
}

/**
 * D-A8 / contract increment A-3: interim identity seam. Sub-issue C replaces the
 * implementation; these assertions describe the pre-C behaviour the acceptance
 * suite pins in the meantime (a formula cell shows and exports its raw text).
 */
describe('worksheetDisplayValues', () => {
  it('returns the raw text for populated cells', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region'], [1, 1, '1200']]));
    expect(display(0, 0)).toBe('Region');
    expect(display(1, 1)).toBe('1200');
  });

  it('returns an empty string for cells that have no stored value', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, 'Region']]));
    expect(display(5, 25)).toBe('');
    expect(display(0, 1)).toBe('');
  });

  it('returns the raw formula text before sub-issue C lands', () => {
    const display = worksheetDisplayValues(sheet([[0, 0, '=1+1']]));
    expect(display(0, 0)).toBe('=1+1');
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import type { WorkbookSnapshot } from '../../../shared/types';
import { ApiClientError, api } from '../api/client';
import { INVALID_CSV_MESSAGE, WORKBOOK_NAME_EMPTY_MESSAGE } from '../lib/copy';
import { Grid } from './Grid';
import { ImportCsvDialog } from './ImportCsvDialog';
import { NewWorkbookPage } from './NewWorkbookPage';
import { RenameWorkbookDialog } from './RenameWorkbookDialog';
import { A1_SELECTION } from '../lib/selection';

const CREATED: WorkbookSnapshot = {
  id: 'wb-new',
  name: 'Untitled spreadsheet',
  updatedAt: '2026-09-29T00:00:00.000Z',
  worksheets: [],
};

/** A file whose `.text()` resolves without depending on jsdom's Blob support. */
function csvFile(name: string, content: string): File {
  const file = new File([content], name, { type: 'text/csv' });
  if (typeof file.text !== 'function') {
    Object.defineProperty(file, 'text', { value: () => Promise.resolve(content) });
  }
  return file;
}

function renderAt(initialEntry: string, element: React.ReactElement) {
  return render(
    <MemoryRouter initialEntries={[initialEntry]}>
      <Routes>
        <Route path="/new" element={element} />
        <Route path="/" element={element} />
        <Route path="/workbook/:id" element={<p>editor opened</p>} />
      </Routes>
    </MemoryRouter>,
  );
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe('NewWorkbookPage (REQ-1-2-1)', () => {
  it('prefills the backend default name', () => {
    renderAt('/new', <NewWorkbookPage />);
    expect(screen.getByLabelText('Workbook name')).toHaveValue('Untitled spreadsheet');
  });

  it('rejects an empty name in place without calling the API', async () => {
    const create = vi.spyOn(api, 'createWorkbook');
    renderAt('/new', <NewWorkbookPage />);
    fireEvent.change(screen.getByLabelText('Workbook name'), { target: { value: '   ' } });
    fireEvent.click(screen.getByRole('button', { name: 'Create' }));

    expect(await screen.findByRole('alert')).toHaveTextContent(WORKBOOK_NAME_EMPTY_MESSAGE);
    expect(create).not.toHaveBeenCalled();
    // Still on the creation page, with the typed value preserved.
    expect(screen.getByLabelText('Workbook name')).toHaveValue('   ');
  });

  it('opens the editor after a successful create', async () => {
    vi.spyOn(api, 'createWorkbook').mockResolvedValue(CREATED);
    renderAt('/new', <NewWorkbookPage />);
    fireEvent.click(screen.getByRole('button', { name: 'Create' }));
    expect(await screen.findByText('editor opened')).toBeTruthy();
  });

  it('keeps the page and input retryable when the server fails', async () => {
    vi.spyOn(api, 'createWorkbook').mockRejectedValue(
      new ApiClientError(500, 'INTERNAL_ERROR', 'Unexpected server error'),
    );
    renderAt('/new', <NewWorkbookPage />);
    fireEvent.change(screen.getByLabelText('Workbook name'), { target: { value: 'Budget' } });
    fireEvent.click(screen.getByRole('button', { name: 'Create' }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Unexpected server error');
    expect(screen.getByLabelText('Workbook name')).toHaveValue('Budget');
    expect(screen.queryByText('editor opened')).toBeNull();
  });
});

describe('RenameWorkbookDialog (REQ-1-2-2)', () => {
  function renderDialog(onRenamed = vi.fn()) {
    render(
      <MemoryRouter>
        <RenameWorkbookDialog
          workbookId="wb-1"
          currentName="Q3 Sales"
          onClose={() => {}}
          onRenamed={onRenamed}
        />
      </MemoryRouter>,
    );
    return onRenamed;
  }

  it('is a dialog named "Rename workbook" with a prefilled name box and Save', () => {
    renderDialog();
    expect(screen.getByRole('dialog', { name: 'Rename workbook' })).toBeTruthy();
    expect(screen.getByLabelText('Workbook name')).toHaveValue('Q3 Sales');
    expect(screen.getByRole('button', { name: 'Save' })).toBeTruthy();
  });

  it('rejects an empty name with the exact message and never calls the API', async () => {
    const rename = vi.spyOn(api, 'renameWorkbook');
    const onRenamed = renderDialog();
    fireEvent.change(screen.getByLabelText('Workbook name'), { target: { value: '  ' } });
    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    expect(await screen.findByRole('alert')).toHaveTextContent(WORKBOOK_NAME_EMPTY_MESSAGE);
    expect(rename).not.toHaveBeenCalled();
    expect(onRenamed).not.toHaveBeenCalled();
  });

  it('reports the persisted name and updatedAt on success', async () => {
    vi.spyOn(api, 'renameWorkbook').mockResolvedValue({
      id: 'wb-1',
      name: 'Q3 Revenue',
      updatedAt: '2026-09-29T01:00:00.000Z',
    });
    const onRenamed = renderDialog();
    fireEvent.change(screen.getByLabelText('Workbook name'), { target: { value: '  Q3 Revenue  ' } });
    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    await waitFor(() => expect(onRenamed).toHaveBeenCalledWith('Q3 Revenue', '2026-09-29T01:00:00.000Z'));
    expect(api.renameWorkbook).toHaveBeenCalledWith('wb-1', 'Q3 Revenue');
  });

  it('shows the server message and keeps the original name when saving fails', async () => {
    vi.spyOn(api, 'renameWorkbook').mockRejectedValue(
      new ApiClientError(500, 'INTERNAL_ERROR', 'Unexpected server error'),
    );
    const onRenamed = renderDialog();
    fireEvent.change(screen.getByLabelText('Workbook name'), { target: { value: 'New name' } });
    fireEvent.click(screen.getByRole('button', { name: 'Save' }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Unexpected server error');
    expect(onRenamed).not.toHaveBeenCalled();
    expect(screen.getByRole('dialog', { name: 'Rename workbook' })).toBeTruthy();
  });
});

describe('ImportCsvDialog (REQ-1-3-1)', () => {
  function renderImport() {
    render(
      <MemoryRouter initialEntries={['/']}>
        <Routes>
          <Route path="/" element={<ImportCsvDialog onClose={() => {}} />} />
          <Route path="/workbook/:id" element={<p>editor opened</p>} />
        </Routes>
      </MemoryRouter>,
    );
  }

  it('is a dialog named "Import CSV" with a labelled file control and Confirm import', () => {
    renderImport();
    expect(screen.getByRole('dialog', { name: 'Import CSV' })).toBeTruthy();
    expect(screen.getByLabelText('CSV file')).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Confirm import' })).toBeTruthy();
  });

  it('posts the file name and UTF-8 text, then opens the editor', async () => {
    const importCsv = vi.spyOn(api, 'importWorkbookCsv').mockResolvedValue(CREATED);
    renderImport();
    fireEvent.change(screen.getByLabelText('CSV file'), {
      target: { files: [csvFile('地区数据.csv', '地区,销售额\n华东,1200')] },
    });
    fireEvent.click(screen.getByRole('button', { name: 'Confirm import' }));

    await waitFor(() =>
      expect(importCsv).toHaveBeenCalledWith('地区数据.csv', '地区,销售额\n华东,1200'),
    );
    expect(await screen.findByText('editor opened')).toBeTruthy();
  });

  it('shows the exact invalid-CSV message and stays open without navigating', async () => {
    vi.spyOn(api, 'importWorkbookCsv').mockRejectedValue(
      new ApiClientError(400, 'INVALID_CSV', INVALID_CSV_MESSAGE),
    );
    renderImport();
    fireEvent.change(screen.getByLabelText('CSV file'), {
      target: { files: [csvFile('broken.csv', 'a,"unterminated')] },
    });
    fireEvent.click(screen.getByRole('button', { name: 'Confirm import' }));

    expect(await screen.findByRole('alert')).toHaveTextContent(INVALID_CSV_MESSAGE);
    expect(screen.queryByText('editor opened')).toBeNull();
    // The dialog and the chosen file stay in place, so the user can retry.
    expect(screen.getByRole('dialog', { name: 'Import CSV' })).toBeTruthy();
    expect((screen.getByLabelText('CSV file') as HTMLInputElement).files).toHaveLength(1);
  });
});

describe('Grid display-value seam (D-A8)', () => {
  it('renders display values while keeping the raw text for editing', () => {
    render(
      <Grid
        rowCount={1}
        colCount={2}
        cells={new Map([['0:0', '=1+1']])}
        displayValue={(row, col) => (row === 0 && col === 0 ? '2' : '')}
        selection={A1_SELECTION}
        editing={null}
        onSelectionChange={() => {}}
        onStartEdit={() => {}}
        onCommitEdit={() => {}}
        onCancelEdit={() => {}}
      />,
    );
    expect(screen.getByRole('gridcell', { name: 'A1' }).textContent).toBe('2');
    expect(screen.getByRole('gridcell', { name: 'B1' }).textContent).toBe('');
  });
});

