import fs from 'node:fs';
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';

/**
 * Sub-issue A acceptance suite (REQ-1-2-1 / 1-2-2 / 1-3-1 / 1-3-2).
 *
 * Runs against the production shape (built frontend served by the backend on
 * one port, throwaway SQLite file) via `bash checks/run-e2e.sh`, and drives the
 * UI exclusively through accessible names, per Issue #1 contract §5.
 *
 * Self-contained: every workbook this suite works with is created through the
 * UI, so it never depends on edits made by `smoke.spec.ts` to the seeded
 * `Q3 Sales` workbook.
 */

const SEED_LINK = { name: 'Q3 Sales', exact: true } as const;

/** Wait until the home page has loaded its list. */
async function gotoHome(page: Page) {
  await page.goto('/');
  await expect(page.getByRole('link', SEED_LINK)).toBeVisible();
}

/** Create a workbook through the UI and return to its editor. */
async function createWorkbook(page: Page, name: string) {
  await gotoHome(page);
  await page.getByRole('button', { name: 'New blank workbook' }).click();
  await expect(page).toHaveURL(/\/new$/);
  await page.getByLabel('Workbook name').fill(name);
  await page.getByRole('button', { name: 'Create' }).click();
  await expect(page).toHaveURL(/\/workbook\/.+/);
}

/** Upload a CSV through the home-page dialog and wait for the editor. */
async function importCsv(page: Page, fileName: string, csv: string) {
  await gotoHome(page);
  await page.getByRole('button', { name: 'Import CSV' }).click();
  const dialog = page.getByRole('dialog', { name: 'Import CSV' });
  await expect(dialog).toBeVisible();
  await page.getByLabel('CSV file').setInputFiles({
    name: fileName,
    mimeType: 'text/csv',
    buffer: Buffer.from(csv, 'utf8'),
  });
  await page.getByRole('button', { name: 'Confirm import' }).click();
  await expect(page).toHaveURL(/\/workbook\/.+/);
}

/** Export the active worksheet and return the suggested name plus text content. */
async function exportCsv(page: Page): Promise<{ fileName: string; csv: string }> {
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.getByRole('button', { name: 'Export CSV' }).click(),
  ]);
  const path = await download.path();
  if (!path) throw new Error('download has no local path');
  return { fileName: download.suggestedFilename(), csv: fs.readFileSync(path, 'utf8') };
}

async function cellText(page: Page, coordinate: string): Promise<string> {
  return (await page.getByRole('gridcell', { name: coordinate, exact: true }).textContent()) ?? '';
}

test.describe('REQ-1-2-1 create a blank workbook', () => {
  test('creates, opens and persists a single blank Sheet1 with A1 selected', async ({ page }) => {
    await gotoHome(page);
    await page.getByRole('button', { name: 'New blank workbook' }).click();
    await expect(page).toHaveURL(/\/new$/);
    await expect(page.getByLabel('Workbook name')).toHaveValue('Untitled spreadsheet');
    await page.getByRole('button', { name: 'Create' }).click();
    await expect(page).toHaveURL(/\/workbook\/.+/);

    // Exactly one worksheet, named Sheet1, active.
    await expect(page.getByRole('tab')).toHaveCount(1);
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    // A1 is selected and the whole default 6x26 structure is blank.
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    await expect(page.getByRole('rowheader')).toHaveCount(6);
    await expect(page.getByRole('columnheader')).toHaveCount(26);
    for (const coordinate of ['A1', 'B2', 'Z6']) {
      expect(await cellText(page, coordinate)).toBe('');
    }

    // Refresh keeps the same state.
    await page.reload();
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
    expect(await cellText(page, 'A1')).toBe('');

    // Returning home and reopening shows the same workbook and state.
    await gotoHome(page);
    await expect(page.getByRole('link', { name: 'Untitled spreadsheet', exact: true })).toBeVisible();
    await page.getByRole('link', { name: 'Untitled spreadsheet', exact: true }).click();
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    await expect(page.getByRole('gridcell', { name: 'A1', exact: true })).toHaveAttribute(
      'aria-selected',
      'true',
    );
  });

  test('rejects an empty name in place and sends no create request', async ({ page }) => {
    let creates = 0;
    page.on('request', (request) => {
      if (request.method() === 'POST' && new URL(request.url()).pathname === '/api/workbooks') {
        creates += 1;
      }
    });

    await gotoHome(page);
    await page.getByRole('button', { name: 'New blank workbook' }).click();
    await page.getByLabel('Workbook name').fill('   ');
    await page.getByRole('button', { name: 'Create' }).click();

    await expect(page.getByRole('alert')).toHaveText('Workbook name cannot be empty');
    await expect(page).toHaveURL(/\/new$/);
    await expect(page.getByLabel('Workbook name')).toHaveValue('   ');
    expect(creates).toBe(0);
  });

  test('shows the error, stays retryable and leaves no record when creation fails', async ({
    page,
  }) => {
    await page.route('**/api/workbooks', async (route) => {
      if (route.request().method() !== 'POST') {
        await route.continue();
        return;
      }
      await route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'Unexpected server error' } }),
      });
    });

    await gotoHome(page);
    await page.getByRole('button', { name: 'New blank workbook' }).click();
    await page.getByLabel('Workbook name').fill('Doomed record');
    await page.getByRole('button', { name: 'Create' }).click();

    await expect(page.getByRole('alert')).toHaveText('Unexpected server error');
    await expect(page).toHaveURL(/\/new$/);
    await expect(page.getByLabel('Workbook name')).toHaveValue('Doomed record');
    await page.unroute('**/api/workbooks');

    // No incomplete record appeared on the home page.
    await gotoHome(page);
    await expect(page.getByRole('link', { name: 'Doomed record', exact: true })).toHaveCount(0);
  });
});

test.describe('REQ-1-2-2 rename a workbook', () => {
  const original = 'Rename target A';
  const renamed = 'Rename target A (renamed)';

  test('renames, keeps the original name on failure and persists the saved name', async ({ page }) => {
    await createWorkbook(page, original);

    // Validation: an empty name is rejected in place with the exact message.
    await page.getByRole('button', { name: 'Rename workbook' }).click();
    const dialog = page.getByRole('dialog', { name: 'Rename workbook' });
    await expect(dialog).toBeVisible();
    await expect(page.getByLabel('Workbook name')).toHaveValue(original);
    await page.getByLabel('Workbook name').fill('   ');
    await page.getByRole('button', { name: 'Save' }).click();
    await expect(page.getByRole('alert')).toHaveText('Workbook name cannot be empty');
    await expect(dialog).toBeVisible();
    await expect(page.getByRole('heading', { name: original, exact: true })).toBeVisible();

    // Server failure: the error is shown and the title keeps the original name.
    await page.route('**/api/workbooks/*', async (route) => {
      if (route.request().method() !== 'PATCH') {
        await route.continue();
        return;
      }
      await route.fulfill({
        status: 500,
        contentType: 'application/json',
        body: JSON.stringify({ error: { code: 'INTERNAL_ERROR', message: 'Unexpected server error' } }),
      });
    });
    await page.getByLabel('Workbook name').fill('Should not stick');
    await page.getByRole('button', { name: 'Save' }).click();
    await expect(page.getByRole('alert')).toHaveText('Unexpected server error');
    await expect(page.getByRole('heading', { name: original, exact: true })).toBeVisible();
    await page.unroute('**/api/workbooks/*');

    // Success: editor title updates immediately.
    await page.getByLabel('Workbook name').fill(`  ${renamed}  `);
    await page.getByRole('button', { name: 'Save' }).click();
    await expect(page.getByRole('heading', { name: renamed, exact: true })).toBeVisible();
    await expect(dialog).toBeHidden();

    // The new name survives a refresh and shows up on the home page instead of the old one.
    await page.reload();
    await expect(page.getByRole('heading', { name: renamed, exact: true })).toBeVisible();
    await gotoHome(page);
    await expect(page.getByRole('link', { name: renamed, exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: original, exact: true })).toHaveCount(0);

    // Reopening shows the most recently saved name.
    await page.getByRole('link', { name: renamed, exact: true }).click();
    await expect(page.getByRole('heading', { name: renamed, exact: true })).toBeVisible();
  });
});

test.describe('REQ-1-3-1 import CSV', () => {
  test('imports UTF-8 text with quotes, escaped quotes, in-field newlines and empty fields', async ({
    page,
  }) => {
    const csv = [
      '地区,销售额,备注',
      '华东,1200,"a,b"',
      'North,800,"say ""hi"""',
      '"multi',
      'line",100,',
    ].join('\n');

    await importCsv(page, 'quarterly report.csv', csv);

    // Name is the file name without its final .csv extension.
    await expect(page.getByRole('heading', { name: 'quarterly report', exact: true })).toBeVisible();
    await expect(page.getByRole('tab')).toHaveCount(1);
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');

    // Row/column order and original text, including the first row as ordinary data.
    const expected: Record<string, string> = {
      A1: '地区',
      B1: '销售额',
      C1: '备注',
      A2: '华东',
      B2: '1200',
      C2: 'a,b',
      A3: 'North',
      B3: '800',
      C3: 'say "hi"',
      A4: 'multi\nline',
      B4: '100',
      C4: '',
    };
    for (const [coordinate, text] of Object.entries(expected)) {
      expect(await cellText(page, coordinate), coordinate).toBe(text);
    }

    // Refresh keeps order and content.
    await page.reload();
    for (const [coordinate, text] of Object.entries(expected)) {
      expect(await cellText(page, coordinate), coordinate).toBe(text);
    }

    // Home page shows the imported workbook under the derived name.
    await gotoHome(page);
    await expect(page.getByRole('link', { name: 'quarterly report', exact: true })).toBeVisible();
  });

  test('rejects an unterminated quote with the exact message and keeps nothing', async ({ page }) => {
    await gotoHome(page);
    await page.getByRole('button', { name: 'Import CSV' }).click();
    const dialog = page.getByRole('dialog', { name: 'Import CSV' });
    await page.getByLabel('CSV file').setInputFiles({
      name: 'broken import.csv',
      mimeType: 'text/csv',
      buffer: Buffer.from('a,b\n"unterminated,c', 'utf8'),
    });
    await page.getByRole('button', { name: 'Confirm import' }).click();

    await expect(page.getByRole('alert')).toHaveText('Invalid CSV file format. Import failed.');
    await expect(dialog).toBeVisible();
    await expect(page).toHaveURL(/\/$/);

    // No link with that name appears, not even after a refresh.
    await expect(page.getByRole('link', { name: 'broken import', exact: true })).toHaveCount(0);
    await page.reload();
    await expect(page.getByRole('link', { name: 'Q3 Sales', exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'broken import', exact: true })).toHaveCount(0);
  });
});

test.describe('REQ-1-3-2 export the current worksheet', () => {
  test('downloads the used range with LF endings and leaves the editor state unchanged', async ({
    page,
  }) => {
    await importCsv(page, 'export basic.csv', ['Region,Sales', 'East,1200', 'North,800'].join('\n'));

    const updatedBefore = await page.getByText(/^Last updated:/).textContent();
    const formulaBar = page.getByRole('textbox', { name: 'Formula bar' });
    const formulaBefore = await formulaBar.inputValue();
    expect(await cellText(page, 'B2')).toBe('1200');

    const { fileName, csv } = await exportCsv(page);

    expect(fileName).toMatch(/\.csv$/);
    expect(csv).toBe('Region,Sales\nEast,1200\nNorth,800\n');
    expect(csv.startsWith('\uFEFF')).toBe(false);
    expect(csv.includes('\r')).toBe(false);

    // Export changes nothing: active worksheet, grid values, formula bar, last-updated.
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    expect(await cellText(page, 'B2')).toBe('1200');
    await expect(formulaBar).toHaveValue(formulaBefore);
    await expect(page.getByText(/^Last updated:/)).toHaveText(updatedBefore ?? '');

    await page.reload();
    await expect(page.getByRole('tab', { name: 'Sheet1' })).toHaveAttribute('aria-selected', 'true');
    expect(await cellText(page, 'B2')).toBe('1200');
    await expect(page.getByText(/^Last updated:/)).toHaveText(updatedBefore ?? '');
  });

  test('escapes commas, quotes and line breaks and keeps empty cells inside the used range', async ({
    page,
  }) => {
    const csv = ['plain,"with,comma"', '"say ""hi""","line', 'break",,tail'].join('\n');
    await importCsv(page, 'export escaping.csv', csv);

    const { csv: exported } = await exportCsv(page);
    expect(exported).toBe('plain,"with,comma",\n"say ""hi""","line\nbreak",,tail\n');
  });

  test('exports an empty file for a blank workbook', async ({ page }) => {
    await createWorkbook(page, 'Empty export source');
    const { fileName, csv } = await exportCsv(page);
    expect(fileName).toMatch(/\.csv$/);
    expect(csv).toBe('');
  });

  test('exports the formula cell value through the shared display seam', async ({ page }) => {
    await importCsv(page, 'export formula.csv', ['=1+1,plain'].join('\n'));

    // PRE-C TRANSITION (Issue #3 decision D-A8): sub-issue C replaces
    // `frontend/src/lib/cellDisplay.ts` with the formula engine. Until then the
    // grid and the export both show the raw formula text. When C lands, this
    // assertion MUST flip to '2' for both the grid cell and the exported text;
    // the integration PR carries that flipped case as the final gate.
    expect(await cellText(page, 'A1')).toBe('=1+1');
    const { csv } = await exportCsv(page);
    expect(csv).toBe('=1+1,plain\n');
  });
});

