import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import type { WorkbookSummary } from '../../../shared/types';
import { api } from '../api/client';
import { lastUpdatedText } from '../lib/format';
import { ErrorBanner } from './ErrorBanner';
import { ImportCsvDialog } from './ImportCsvDialog';

/**
 * Workbook home page: the entry point that lists available workbooks and hosts
 * the two workbook-creation entry points.
 *
 * - `New blank workbook` is a button (not a link) that opens `/new` (D-A1).
 * - `Import CSV` opens the import dialog (D-A6).
 *
 * The list is fetched on every mount, so returning here after creating,
 * renaming or importing always shows the persisted names — and a failed
 * attempt shows nothing extra.
 */
export function HomePage() {
  const navigate = useNavigate();
  const [workbooks, setWorkbooks] = useState<WorkbookSummary[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [importOpen, setImportOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;
    api
      .listWorkbooks()
      .then((list) => {
        if (!cancelled) setWorkbooks(list);
      })
      .catch((caught: unknown) => {
        if (!cancelled) setError(caught instanceof Error ? caught.message : String(caught));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <div className="min-h-screen bg-sheet-bg">
      <header className="flex h-14 items-center gap-3 border-b-1 border-sheet-border bg-white px-6">
        <span aria-hidden="true" className="text-xl">
          ▦
        </span>
        <span className="text-base font-medium text-sheet-text">Spreadsheet Data Workspace</span>
      </header>

      <main className="mx-auto max-w-4xl px-6 py-8">
        <h1 className="mb-4 text-xl font-medium text-sheet-text">Workbooks</h1>
        <div className="mb-5 flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() => navigate('/new')}
            className="rounded bg-sheet-accent px-4 py-1.5 text-sm text-white hover:bg-#1765cc"
          >
            New blank workbook
          </button>
          <button
            type="button"
            onClick={() => setImportOpen(true)}
            className="rounded border-1 border-sheet-border bg-white px-4 py-1.5 text-sm text-sheet-text hover:bg-#f1f3f4"
          >
            Import CSV
          </button>
        </div>
        <ErrorBanner message={error} />
        {workbooks === null && !error ? (
          <p className="text-sm text-sheet-muted">Loading workbooks…</p>
        ) : null}
        {workbooks?.length === 0 ? (
          <p className="text-sm text-sheet-muted">No workbooks yet.</p>
        ) : null}
        {workbooks && workbooks.length > 0 ? (
          <ul className="overflow-hidden rounded-lg border-1 border-sheet-border bg-white">
            {workbooks.map((workbook, index) => (
              <li
                key={workbook.id}
                className={
                  'flex items-center justify-between gap-4 px-4 py-3 hover:bg-#f1f3f4' +
                  (index > 0 ? ' border-t-1 border-sheet-border' : '')
                }
              >
                <Link
                  to={`/workbook/${encodeURIComponent(workbook.id)}`}
                  className="text-sm font-medium text-sheet-text hover:underline"
                >
                  {workbook.name}
                </Link>
                <span className="shrink-0 text-xs text-sheet-muted">
                  {lastUpdatedText(workbook.updatedAt)}
                </span>
              </li>
            ))}
          </ul>
        ) : null}
      </main>
      {importOpen ? <ImportCsvDialog onClose={() => setImportOpen(false)} /> : null}
    </div>
  );
}

